def privacy(lang):
    en=lang=='en'
    title='Data and privacy' if en else 'Podatki in zasebnost'
    sections=[
        ('Personal use, on your device','You can use Jivie for personal tasks, plans, shopping and finances without an account. These records are stored on your device. The active local database does not have additional encryption provided by the app; protection also depends on your device and operating system.'),
        ('Connecting your own server','For optional synchronization and sharing, you connect a compatible Kanboard server with the FamilyHub plugin. Signing in alone does not upload your personal content. You explicitly enable private synchronization; shared content is available according to the permissions of its space. The server processes account data, sessions, memberships, submitted content and technical data needed for operation and security. Its operator controls the deployment, logs, service providers and backups. TriparNA does not currently offer managed Jivie hosting.'),
        ('Reminders and notifications','Local reminders use your device’s notification system and permissions. Remote notifications use Firebase Cloud Messaging and require compatible server configuration, explicit device registration and operating-system permission. In the current version, categories without saved preferences have push and in-app notifications enabled, with email and sound disabled. Your saved choices, including explicit opt-outs, take precedence. Older servers may use different category defaults. Delivery processes device tokens, technical SDK metadata and generic messages with record references; our push message does not contain task titles or financial amounts. This channel is not automatically available for arbitrary self-hosted servers. Android delivery has been tested on our test server; the iOS APNs connection is still being prepared. macOS currently has the in-app centre, without remote system push. Email delivery requires separate server configuration and may use a verified email address for security codes or enabled notifications.'),
        ('Backups and exports','A portable .vsakdan backup is encrypted with a password you choose and saved to a location you select. It includes editable idea boards and their downloaded photo bytes. Missing photo downloads are marked incomplete. It does not include login sessions or unrelated server attachments and is not a complete server backup. When a restored server space is converted to standalone local use, transfers between financial accounts and linked payments are not activated as new local records. Their originals remain in the encrypted recovery archive, and the financial view is marked incomplete. The advanced JSON export is unencrypted. You control the copies you export and where they are stored.'),
        ('Deleting data',f'Signing out does not delete your account or all local data. See <a href="{url(lang,"delete-account")}">account deletion</a> for the self-hosted account process. Server deletion cannot recall copies other members already obtained or exports you saved elsewhere. Your server operator is responsible for the handling of its logs and backups. The deletion screen explains which active data is affected before confirmation.'),
        ('This website','This static website does not use analytics, advertising trackers or cookies set by its own code. Fonts, images and scripts are served from this website. The hosting infrastructure may process normal technical request data, such as IP addresses, to deliver and protect the site. Entering a server address on the deletion page only prepares a link in your browser; this page does not check your account or send login credentials. Opening the link connects you to the server you selected.'),
        ('Contact and requests',f'Jivie is published by {escape(PUBLISHER)}, Jablanica 18, 8294 Boštanj, Slovenia. For questions about the app, this website or privacy, contact <a href="mailto:{EMAIL}">{EMAIL}</a>. For access, correction or deletion of data on a self-hosted server, contact that server’s operator. Do not email passwords, sign-in codes, API keys or personal backups.')
    ] if en else [
        ('Osebna uporaba na tvoji napravi','Jivie lahko uporabljaš za osebna opravila, načrte, nakupe in finance brez računa. Ti zapisi se hranijo na napravi. Aktivna lokalna baza nima dodatnega šifriranja v aplikaciji; zaščita je odvisna tudi od naprave in operacijskega sistema.'),
        ('Povezava z lastnim strežnikom','Za izbirno sinhronizacijo in sodelovanje povežeš združljiv strežnik Kanboard z vtičnikom FamilyHub. Prijava sama ne prenese osebnih vsebin. Zasebni prenos omogočiš izrecno; skupna vsebina je dostopna glede na pravice prostora. Strežnik obdeluje podatke računa, seje, članstva, poslane vsebine ter tehnične podatke za delovanje in varnost. Njegov upravljavec določa konfiguracijo, dnevnike, ponudnike in varnostne kopije. TriparNA trenutno ne ponuja upravljanega gostovanja Jivie.'),
        ('Opomniki in obvestila','Lokalni opomniki uporabljajo sistem obvestil in dovoljenja naprave. Oddaljena obvestila uporabljajo Firebase Cloud Messaging ter zahtevajo združljivo nastavitev strežnika, izrecno registracijo naprave in dovoljenje operacijskega sistema. V trenutni različici imajo kategorije brez shranjenih nastavitev vključena push in obvestila v aplikaciji, e-pošta in zvok pa sta izključena. Tvoje shranjene izbire, tudi izrecni izklopi, imajo prednost. Starejši strežniki imajo lahko drugačne privzete nastavitve kategorij. Za dostavo se obdelujejo žetoni naprave, tehnični podatki SDK in generična sporočila z referencami; naše push sporočilo ne vsebuje naslovov opravil ali finančnih zneskov. Kanal pri poljubnem samostojnem gostovanju ni samodejno na voljo. Android dostava je preverjena na našem testnem strežniku; povezava iOS APNs je še v pripravi. macOS trenutno uporablja center v aplikaciji, brez oddaljenega sistemskega push. E-pošta zahteva ločeno nastavitev strežnika in lahko uporablja preverjeni naslov za varnostne kode ali omogočena obvestila.'),
        ('Varnostne kopije in izvozi','Prenosna kopija .vsakdan je šifrirana z geslom, ki ga izbereš, in shranjena na izbrano lokacijo. Vsebuje uredljive table Idejnika in bajte njihovih prenesenih fotografij. Manjkajoči prenosi slik so označeni kot nepopolnost. Ne vsebuje prijavnih sej ali drugih strežniških priponk in ni popolna kopija strežnika. Pri pretvorbi obnovljenega strežniškega prostora v samostojno lokalno uporabo se prenosi med finančnimi računi in povezave plačil ne aktivirajo kot novi lokalni zapisi. Izvirniki ostanejo v šifriranem obnovitvenem arhivu, finančni pregled pa je označen kot nepopoln. Napredni JSON izvoz je nešifriran. Izvožene kopije in mesto njihove hrambe upravljaš sam.'),
        ('Brisanje podatkov',f'Odjava ne izbriše računa ali vseh lokalnih podatkov. Postopek za samostojni strežnik je opisan na strani <a href="{url(lang,"delete-account")}">Izbris računa</a>. Strežniški izbris ne more odpoklicati kopij, ki so jih drugi člani že pridobili, ali izvozov, shranjenih drugje. Za ravnanje z dnevniki in varnostnimi kopijami strežnika je odgovoren njegov upravljavec. Zaslon za izbris pred potrditvijo pojasni, kateri aktivni podatki so vključeni.'),
        ('Ta spletna stran','Ta statična stran v svoji kodi ne uporablja analitike, oglaševalskih sledilnikov ali piškotkov. Pisave, slike in skripte se nalagajo s te strani. Infrastruktura gostovanja lahko za dostavo in zaščito strani obdeluje običajne tehnične podatke zahtev, na primer naslov IP. Vnos naslova strežnika na strani za izbris samo pripravi povezavo v brskalniku; stran ne preverja računa in ne pošilja prijavnih podatkov. Z odprtjem povezave se povežeš z izbranim strežnikom.'),
        ('Kontakt in zahtevki',f'Jivie izdaja {escape(PUBLISHER)}, Jablanica 18, 8294 Boštanj. Za vprašanja o aplikaciji, tej strani ali zasebnosti piši na <a href="mailto:{EMAIL}">{EMAIL}</a>. Za dostop, popravek ali izbris podatkov na samostojnem strežniku se obrni na njegovega upravljavca. Po e-pošti ne pošiljaj gesel, prijavnih kod, API ključev ali osebnih varnostnih kopij.')
    ]
    sections.insert(2, ('Idea boards and photos', 'Idea boards contain text, drawings, annotations and photos you select with the system file picker. The app stores a normalized copy of the photo and removes its embedded metadata. Local boards and drafts remain on the device. Saving a shared board or explicitly enabling private synchronization sends its content and normalized photos to the selected compatible server. Its operator and authorized members can access that shared content. Downloaded photos are cached for offline use; a remote link alone is not an offline copy. Image transfer is over HTTPS; active local storage and private server storage do not add end-to-end encryption.') if en else ('Idejnik in fotografije', 'Table Idejnika vsebujejo besedilo, risbe, oznake in fotografije, ki jih izbereš s sistemskim izbirnikom datotek. Aplikacija shrani normalizirano kopijo fotografije in odstrani njene vgrajene metapodatke. Lokalne table in osnutki ostanejo na napravi. Shranjevanje skupne table ali izrecni vklop zasebne sinhronizacije pošlje njeno vsebino in normalizirane fotografije na izbrani združljivi strežnik. Njegov upravljavec in upravičeni člani lahko dostopajo do te skupne vsebine. Prenesene fotografije se hranijo za delo brez povezave; oddaljena povezava sama ni lokalna kopija. Prenos slik uporablja HTTPS; aktivna lokalna in zasebna strežniška hramba ne dodajata šifriranja od pošiljatelja do prejemnika.'))
    sections.insert(3, ('Shared-content rules and reports', 'Before publishing shared changes on a compatible FamilyHub server, you explicitly accept that server’s shared-content rules. The policy version and time are recorded for your account there. Local personal use and private personal synchronization are separate. Before reporting a shared item or member, you review the recipient and evidence: selected text or member identity, or the exact idea board and its photos. The report goes to your selected server administrator; TriparNA does not automatically receive it. It excludes login secrets, other spaces and unrelated private finances. Reporting does not automatically remove content. The plugin clears report details, evidence and review notes 180 days after resolution when cleanup runs; open reports remain for review and minimal process records remain. Your server operator handles reviews, cleanup, logs and server backups. Account deletion describes its impact on reports before confirmation.') if en else ('Pravila deljenja in prijave', 'Pred objavo skupnih sprememb na združljivem strežniku FamilyHub izrecno sprejmeš njegova pravila skupne vsebine. Različica pravil in čas se shranita pri tvojem računu na tem strežniku. Osebna lokalna uporaba in zasebna osebna sinhronizacija sta ločeni. Pred prijavo skupne vsebine ali člana pregledaš prejemnika in posnetek: izbrana besedilna polja ali identiteto člana oziroma natančno tablo Idejnika z njenimi fotografijami. Prijavo prejme skrbnik izbranega strežnika; TriparNA je ne prejme samodejno. Posnetek ne zajema prijavnih skrivnosti, drugih prostorov ali nepovezanih zasebnih financ. Prijava sama ne odstrani vsebine. Vtičnik odstrani podrobnosti, posnetek in zapiske obravnave 180 dni po zaključku prijave, ko se izvede čiščenje; odprte prijave ostanejo za obravnavo, minimalna evidenca postopka pa ostane. Za obravnavo, čiščenje, dnevnike in strežniške kopije skrbi upravljavec tvojega strežnika. Izbris računa svoj vpliv na prijave prikaže pred potrditvijo.'))
    intro='How data is handled in the local app, on your own server and on this website.' if en else 'Kako ravnamo s podatki v lokalni aplikaciji, na tvojem strežniku in na tej spletni strani.'
    content=f'<p class="eyebrow">Jivie · {"12 October 2026" if en else "12. oktober 2026"}</p><h1>{title}</h1><p class="lead">{intro}</p>'+''.join(f'<section><h2>{h}</h2><p>{p}</p></section>' for h,p in sections)
    page(lang,'privacy',title,intro,content)


def help_page(lang):
    en=lang=='en'
    title='A small guide to getting started' if en else 'Majhen vodič za dober začetek'
    intro='Start with one useful thing. Connect the rest when you need it.' if en else 'Začni z eno uporabno stvarjo. Ostalo poveži, ko ti pride prav.'
    items=[('Do I need an account?','No. Choose local use and create your first task, plan or shopping list. Personal work is saved on your device, even without a connection.','local'),('Where do I find things?','The four main destinations are Pulse, Planner, Space and More. Pulse shows today’s events, the next seven days, projects in progress and tasks. Planner contains Tasks, Calendar and Ideas. Space contains Projects and Finances, with Shopping, Garden and People where the selected space supports them. The garden keeps its own beds and seasons. More contains your account, space settings, app settings, backups and help. Android and iOS use the same four bottom tabs; desktop uses the same groups in a sidebar. Choose your space in the top selector. All combines the content you can access; choose a specific space before adding content. Members, invitations and sharing are managed in Space settings.','navigation'),('How do I keep a backup?','Open More → Backups and create an encrypted portable copy. Keep its password safe: the backup cannot be restored without it. The copy contains supported records, editable idea boards and downloaded idea photos; missing image downloads are marked incomplete. It excludes login sessions and unrelated server attachments and is not a complete server backup. Converting a restored server space to standalone local use leaves financial transfers and linked payments in the encrypted recovery archive; the local financial view remains incomplete. Before changing devices, check that you can restore the copy. Synchronization is not a backup.','backup'),('How do I share with others?','Connect an HTTPS Kanboard server with the compatible FamilyHub plugin and its Native API enabled. The server operator prepares the first account or an invitation. Manage invitations in Space settings. The inviter enters your email address; open the emailed link, create an account or sign in, then accept the invitation separately. Joining a whole household or organization gives access to its shared content, finances and all existing and future projects. A project-only invitation gives access only to that project, its tasks, events, notifications and finances, without membership in its parent space. Within the shared scope, members can create, edit, delete, manage finances and invite or manage members. Ownership protections remain, and older sharing policies require an explicit transition preview. A Kanboard server without the plugin does not provide these collaboration features. Connecting does not automatically upload your personal content.','server'),('What about notifications?','Local reminders need notification permission and a record available on the device. The shared notification centre refreshes when connected or synchronized. In the current version, categories without saved preferences enable in-app and push notifications; email and sound are off. Explicit saved opt-outs remain. Remote phone delivery also needs compatible server configuration, explicit device registration and operating-system permission; defaults alone do not register a device. Mark all as read applies to the current filter and does not complete tasks or payments. Remote phone notifications with the app closed are not automatically available for every self-hosted server.','notifications'),('What if I cannot sign in?','Check your server address and contact the server operator. Email password recovery requires server support and a previously verified email address. Never send your password or one-time codes to support.','login')]
    if not en:
        items=[('Ali potrebujem račun?','Ne. Izberi lokalno uporabo in dodaj prvo opravilo, načrt ali nakupovalni seznam. Osebno delo se shrani na napravi, tudi brez povezave.','local'),('Kje najdem posamezne stvari?','Štirje glavni cilji so Utrip, Planer, Prostor in Več. Utrip pokaže današnje dogodke, naslednjih sedem dni, projekte v teku in opravila. Planer vsebuje Opravila, Koledar in Idejnik. Prostor vsebuje Projekte in Finance ter Nakupovanje, Vrt in Osebe, kjer jih izbrani prostor podpira. Vrt ohrani svoje grede in sezone. Več vsebuje račun, nastavitve prostora, nastavitve aplikacije, kopije in pomoč. Android in iOS uporabljata iste štiri spodnje zavihke; namizje iste skupine v stranskem meniju. Prostor izbereš v zgornjem izboru. Vsi združi vsebino, do katere imaš dostop; pred dodajanjem izberi določen prostor. Člane, povabila in deljenje upravljaš v Nastavitvah prostora.','navigation'),('Kako ohranim varnostno kopijo?','Odpri Več → Kopije in ustvari šifrirano prenosno kopijo. Geslo shrani varno: brez njega kopije ne moreš obnoviti. Kopija vsebuje podprte zapise, uredljive table in prenesene fotografije Idejnika; manjkajoči prenosi slik so označeni kot nepopolnost. Ne vsebuje prijavnih sej ali drugih strežniških priponk in ni popolna kopija strežnika. Pri pretvorbi obnovljenega strežniškega prostora v samostojno lokalno uporabo finančni prenosi in povezave plačil ostanejo v šifriranem obnovitvenem arhivu; lokalni finančni pregled je nepopoln. Pred menjavo naprave preveri, da obnova deluje. Sinhronizacija ni varnostna kopija.','backup'),('Kako delim z drugimi?','Poveži HTTPS strežnik Kanboard z združljivim vtičnikom FamilyHub in omogočenim Native API. Prvi račun ali povabilo pripravi upravljavec strežnika. Povabila upravljaš v Nastavitvah prostora. Pošiljatelj vnese tvoj e-poštni naslov; odpri poštno povezavo, ustvari račun ali se prijavi, nato povabilo posebej sprejmi. Članstvo celotnega gospodinjstva ali organizacije odpre njeno skupno vsebino, finance ter vse obstoječe in prihodnje projekte. Povabilo samo v projekt odpre le ta projekt, njegova opravila, dogodke, obvestila in finance, brez članstva nadrejenega prostora. Člani lahko v deljenem obsegu ustvarjajo, urejajo, brišejo, upravljajo finance ter vabijo in upravljajo člane. Zaščita lastništva ostane, stare politike deljenja pa zahtevajo izrecen predogled prehoda. Kanboard brez vtičnika teh možnosti sodelovanja ne zagotavlja. Povezovanje osebne vsebine ne prenese samodejno.','server'),('Kako delujejo obvestila?','Lokalni opomniki potrebujejo dovoljenje za obvestila in zapis, ki je na napravi. Center skupnih obvestil se osveži ob povezavi oziroma sinhronizaciji. V trenutni različici imajo kategorije brez shranjenih nastavitev vključena obvestila v aplikaciji in push; e-pošta in zvok sta izključena. Shranjeni izrecni izklopi ostanejo. Oddaljena telefonska dostava potrebuje tudi združljivo nastavitev strežnika, izrecno registracijo naprave in dovoljenje operacijskega sistema; privzete vrednosti same naprave ne registrirajo. Označi vse kot prebrano velja za trenutni filter in ne zaključi opravil ali plačil. Oddaljena telefonska obvestila ob zaprti aplikaciji niso samodejno na voljo za vsak samostojni strežnik.','notifications'),('Kaj če se ne morem prijaviti?','Preveri naslov strežnika in se obrni na njegovega upravljavca. Obnova gesla po e-pošti potrebuje podporo strežnika in predhodno preverjen naslov. Podpori nikoli ne pošiljaj gesla ali enkratnih kod.','login')]
    items.insert(2, ('How do idea boards work?', 'Open Planner → Ideas. Add text, notes, photos or drawings to a board. Select a photo to attach markings and notes so they follow it when moved, resized or rotated. Drafts stay on your device; Save commits the board and prepares synchronization and an activity notification in a shared space. Private personal boards stay private. Photo availability is shown explicitly when a download is missing.', 'ideas') if en else ('Kako uporabljam Idejnik?', 'Odpri Planer → Idejnik. Na tablo dodaj besedilo, opombe, fotografije ali risbe. Izberi fotografijo, da nanjo vežeš oznake in opombe; te ji sledijo pri premiku, povečavi ali vrtenju. Osnutki ostanejo na napravi; Shrani potrdi tablo in v deljenem prostoru pripravi sinhronizacijo ter obvestilo o spremembi. Zasebne osebne table ostanejo zasebne. Manjkajoč prenos fotografije je prikazan.', 'ideas'))
    body=''.join(f'<section id="{id}"><h2>{q}</h2><p>{a}</p></section>' for q,a,id in items)
    body+=f'<section><h2>{"How do I delete my account?" if en else "Kako izbrišem račun?"}</h2><p><a href="{url(lang,"delete-account")}">{"See the self-hosted account deletion process." if en else "Odpri postopek izbrisa računa na samostojnem strežniku."}</a></p></section>'
    body+=f'<section><h2>{"Need a hand?" if en else "Potrebuješ pomoč?"}</h2><p>{"Tell us the app version, your operating system and what happened. Remove personal data from screenshots." if en else "Opiši težavo, različico aplikacije in operacijski sistem. Iz posnetkov odstrani osebne podatke."} <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></section>'
    page(lang,'help',title,intro,f'<p class="eyebrow">Jivie · {"Help" if en else "Pomoč"}</p><h1>{title}</h1><p class="lead">{intro}</p>{body}')


def delete_page(lang):
    en=lang=='en'
    title='Delete your self-hosted account' if en else 'Izbris računa na lastnem strežniku'
    intro='The process takes place on the server where your account lives.' if en else 'Postopek poteka na strežniku, kjer imaš svoj račun.'
    body=f'''<p class="eyebrow">Jivie · {"Account and data" if en else "Račun in podatki"}</p><h1>{title}</h1><p class="lead">{intro}</p>
<p>{'Local-only use has no server account. This page is for accounts on a self-hosted Kanboard server with the FamilyHub plugin. TriparNA cannot access those accounts simply because you use Jivie.' if en else 'Pri uporabi samo na napravi strežniškega računa nimaš. Ta stran velja za račune na samostojnem strežniku Kanboard z vtičnikom FamilyHub. TriparNA do teh računov nima dostopa samo zato, ker uporabljaš Jivie.'}</p>
<div class="notice"><p>{'Export what you want to keep before deletion. Jivie currently uses the same user account as Kanboard: deleting that account also removes its Kanboard sign-in. Signing out or uninstalling the app does not delete the server account.' if en else 'Pred izbrisom izvozi, kar želiš ohraniti. Jivie trenutno uporablja isti uporabniški račun kot Kanboard: izbris tega računa odstrani tudi njegovo prijavo v Kanboard. Odjava ali odstranitev aplikacije nista izbris strežniškega računa.'}</p></div>
<h2>{'Open your server’s deletion page' if en else 'Odpri stran za izbris na svojem strežniku'}</h2>
<p>{'Enter only the base address of your Kanboard server. This page prepares a link; it does not connect to the server or send a deletion request. You sign in and confirm on your own server.' if en else 'Vnesi samo osnovni naslov svojega Kanboard strežnika. Ta stran pripravi povezavo; ne poveže se s strežnikom in ne pošlje zahteve za izbris. Prijavo in potrditev opraviš na svojem strežniku.'}</p>
<form class="server-form" data-server-form data-error-message="{'Enter an HTTPS base address without a username, password, query, fragment or index.php. Example: https://board.example.org/kanboard/' if en else 'Vnesi osnovni HTTPS naslov brez uporabniškega imena, gesla, parametrov, fragmenta ali index.php. Primer: https://board.example.org/kanboard/'}"><label for="server">{'Your server address' if en else 'Naslov tvojega strežnika'}</label><input id="server" type="url" inputmode="url" autocomplete="off" spellcheck="false" required placeholder="https://board.example.org/kanboard/" aria-describedby="server-hint server-error"><p class="hint" id="server-hint">{'Do not enter passwords, sign-in codes or invitation links here.' if en else 'Sem ne vpisuj gesel, prijavnih kod ali povezav s povabili.'}</p><button class="button primary" type="submit">{'Prepare link' if en else 'Pripravi povezavo'} <span aria-hidden="true">↗</span></button><p class="error" id="server-error" data-error role="alert"></p><div class="server-result" data-result hidden><p>{'Continue on:' if en else 'Nadaljuješ na:'} <strong data-host></strong></p><a class="button primary" data-server-link target="_blank" rel="noopener noreferrer">{'Open my server' if en else 'Odpri moj strežnik'} ↗</a><p class="hint">{'Check the address before signing in. A compatible FamilyHub version with account deletion enabled is required.' if en else 'Pred prijavo preveri naslov. Potrebna je združljiva različica FamilyHub z omogočenim izbrisom računa.'}</p></div><noscript><p>{'Enable JavaScript to prepare the link, or open your Kanboard server and use its FamilyHub account deletion page. No password should be entered on jivie.app.' if en else 'Za pripravo povezave omogoči JavaScript ali odpri svoj Kanboard strežnik in njegovo stran FamilyHub za izbris računa. Na jivie.app ne vpisuj gesla.'}</p></noscript></form>
<h2>{'Before you confirm' if en else 'Pred potrditvijo'}</h2><p>{'Your server shows the affected data and any ownership issues that need resolving. Personal synchronized data, access and shared contributions are handled according to that preview. If you explicitly choose to retain or transfer a shared space or project, its already shared financial facts, including costs, payments and reimbursements, may remain. Personal financial projections and links to private accounts are removed as described in the preview. Some historical identifiers may remain; this is not complete anonymization. The process may require an ownership transfer or an explicit choice for shared structures.' if en else 'Strežnik pokaže prizadete podatke in morebitna lastništva, ki jih je treba urediti. Sinhronizirani osebni podatki, dostop in skupni prispevki se obravnavajo po tem predogledu. Če izrecno izbereš ohranitev ali prenos skupnega prostora oziroma projekta, se lahko ohranijo njegova že deljena finančna dejstva, tudi stroški, plačila in povračila. Osebne finančne projekcije in povezave do zasebnih računov se odstranijo po opisu v predogledu. Nekateri zgodovinski identifikatorji lahko ostanejo; to ni popolna anonimizacija. Postopek lahko zahteva prenos lastništva ali izrecno izbiro za skupne strukture.'}</p>
<p>{'Records created by other members remain, including edits you made to their content. A shared shopping list or financial account needed by other members can remain after an explicit choice, with identifying fields removed; the preview explains any retained balance. Some older Kanboard tasks contain contributions from several people and require resolving those dependencies before deletion.' if en else 'Zapisi, ki so jih ustvarili drugi člani, ostanejo, tudi z vašimi popravki njihove vsebine. Skupni nakupovalni seznam ali finančni račun, ki ga potrebujejo drugi člani, lahko po izrecni izbiri ostane z odstranjenimi osebnimi oznakami; predogled pojasni tudi morebitno ohranjeno stanje. Pri nekaterih starejših Kanboardovih opravilih s prispevki več ljudi je treba pred izbrisom najprej urediti te odvisnosti.'}</p>
<h2>{'If your server does not support this page' if en else 'Če strežnik te strani še ne podpira'}</h2><p>{'Ask its operator to update FamilyHub and enable the self-hosted deletion feature. This public site cannot perform deletion on an incompatible or unreachable server and does not show a deletion as complete without that server’s confirmation.' if en else 'Upravljavca prosi za nadgradnjo FamilyHub in vključitev izbrisa za samostojno gostovanje. Ta javna stran ne more izvesti izbrisa na nezdružljivem ali nedosegljivem strežniku in ne prikazuje izbrisa kot opravljenega brez njegove potrditve.'}</p>
<h2>{'Copies and backups' if en else 'Kopije in varnostne kopije'}</h2><p>{'Deletion cannot recall exports or copies other members already obtained. The server operator handles logs and server backups. Standalone local personal data is separate from the server account. Managed hosting is not offered at this stage and will have its own published rules if introduced.' if en else 'Izbris ne more odpoklicati izvozov ali kopij, ki so jih drugi člani že pridobili. Dnevnike in strežniške varnostne kopije ureja upravljavec strežnika. Samostojni lokalni osebni podatki so ločeni od strežniškega računa. Upravljanega gostovanja v tej fazi ne ponujamo; ob uvedbi bo imelo svoja objavljena pravila.'}</p>
<p>{'Questions about the app?' if en else 'Vprašanja o aplikaciji?'} <a href="mailto:{EMAIL}">{EMAIL}</a>.</p>'''
    page(lang,'delete-account',title,intro,body)


def main():
    for lang in ('sl','en'):
        home(lang); privacy(lang); help_page(lang); delete_page(lang)
    urls=''.join(f'<url><loc>https://jivie.app{url(lang,slug)}</loc></url>' for lang in ('sl','en') for slug in ('','privacy','help','delete-account'))
    ROOT.joinpath('sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>\n',encoding='utf-8')
    print('Rendered 8 static pages into website/public/.')


if __name__ == '__main__':
    main()
